#!/usr/bin/env python3
"""
Round 129b (culprits), 2 October 2026. Needs round 128b.

Blacklisted fishing vessels where each was last seen.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

HEAD = "## Round 129b (2 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round129b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 128b" not in text:
        sys.exit("round129b: round 128b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round129b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round129b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round129b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


NOTE = '## Round 129b (2 October)\n\nNeeds round 128b. Tiles patch round129b_tiles.py beside it. No app.js?v= bump.\n\n- iuu_positions (geojsonlive iuu/positions.geojson) after iuu_vessels under\n  Fishing and Environmental crime. The 2 October build read 212 vessels but\n  placed none: positions are written as "Yantai, China / Bohai Sea". Tiles\n  iuu_vessels.py now places them at the port, else the sea, by Nominatim\n  (cached in iuu/places.json; box says so), and drops the history-table rows\n  that were read as labels (779 fields down to 44).\n- Tiles medical_culprits.py: the settlements table is read as a full grid\n  with rowspan/colspan (grid()); the 123b left-shift guess took drug names\n  ("Neurontin", "Claritin") as companies when a middle column spanned rows.\n- Tiles nusantara_health.py: the 101b probe asked every layer for one square\n  over Kalimantan, so layers elsewhere read as empty. Now also asks each\n  layer where its own data is (first WFS feature, else its area\'s middle),\n  with each listed style, and how many features it holds. Run by hand, then\n  decide which of the 12 "draw nothing" layers are really empty.\n\n'
DIFF = ''

if __name__ == "__main__":
    main()
